import polars as p,json
D=p.read_parquet('/home/davidcondrey/vibe-hms/export-final/summary.parquet')
o={}
for a in D['algorithm'].unique():
 d=D.filter(p.col('algorithm')==a)
 o[a]={'count':d.height,'max_recall':d['recall'].max(),'max_row':d.sort('recall',descending=True).head(1).to_dicts(),'best':{}}
 for t in [.9,.95,.99]:
  x=d.filter(p.col('recall')>=t).sort('qps',descending=True).head(1)
  o[a]['best'][str(t)]=x.to_dicts()
print(json.dumps(o,indent=2))

