  with h5py.File(root+'/results/llama-128-ip/100/'+alg+'/'+f,'r') as h:
   x=h[g]; ids=x['neighbors'][:]
   out[alg+'/'+f+'/'+g]={'stored_recall':float(np.mean(x['recalls'][:]/100)),'id_recall':float(np.mean([len(set(a)&set(b))/100 for a,b in zip(ids,truth)])),'duplicate_queries':int(sum(len(set(a))!=100 for a in ids)),'run_count':int(x.attrs['run_count']),'qps':float(x.attrs['best_qps']),'attrs':{k:str(v) for k,v in x.attrs.items()}}
